using CardPlatform.Contracts;

namespace CardPlatform.Messaging.Outbox;

/// <summary>
/// A row of the transactional outbox (<c>outbox_messages</c>): an integration event written in the same database
/// transaction as the change it describes, and published to Kafka later (ADR 0003). Shared by every service that
/// publishes events (the Authorization now, the Fraud Worker later), so they store and publish them the same way.
/// </summary>
/// <remarks>
/// <see cref="Id"/> is the row's own key, generated by the database. <see cref="EventId"/> is not unique: a producer may
/// give a deterministic event id to an event that can be written more than once (e.g. by concurrent writers that
/// converge on the same state), so the duplicates carry the same id and consumers, which process each event id once,
/// drop all but the first.
/// </remarks>
public sealed class OutboxMessage
{
    private OutboxMessage(
        Guid eventId,
        string type,
        string partitionKey,
        string topic,
        string payload,
        DateTimeOffset createdAt)
    {
        EventId = eventId;
        Type = type;
        PartitionKey = partitionKey;
        Topic = topic;
        Payload = payload;
        CreatedAt = createdAt;
    }

    /// <summary>
    /// Row id (identity), also the order in which rows were written: the publisher sends the rows in this order (see
    /// ADR 0010 for what that guarantees).
    /// </summary>
    public long Id { get; private set; }

    /// <summary>The <see cref="EventEnvelope.EventId"/> of the event.</summary>
    public Guid EventId { get; private set; }

    /// <summary>The <see cref="EventEnvelope.Type"/> of the event (see <see cref="EventTypes"/>).</summary>
    public string Type { get; private set; }

    /// <summary>The Kafka message key (<see cref="EventEnvelope.PartitionKey"/>, the card id).</summary>
    public string PartitionKey { get; private set; }

    /// <summary>The topic the event is published on (see <see cref="Topics"/>).</summary>
    public string Topic { get; private set; }

    /// <summary>The whole envelope as JSON, written with <see cref="EventSerializer"/>.</summary>
    public string Payload { get; private set; }

    /// <summary>When the row was written (UTC, whole microseconds).</summary>
    public DateTimeOffset CreatedAt { get; private set; }

    /// <summary>When the event was published; <see langword="null"/> until then.</summary>
    public DateTimeOffset? PublishedAt { get; private set; }

    /// <summary>How many times publishing the event was attempted.</summary>
    public int Attempts { get; private set; }

    /// <summary>
    /// A new, unpublished row for <paramref name="envelope"/> on <paramref name="topic"/>. <paramref name="createdAt"/> is
    /// stored in UTC and truncated to whole microseconds, the precision PostgreSQL keeps.
    /// </summary>
    public static OutboxMessage Create(EventEnvelope envelope, string topic, DateTimeOffset createdAt)
    {
        ArgumentNullException.ThrowIfNull(envelope);
        ArgumentException.ThrowIfNullOrWhiteSpace(topic);

        return new OutboxMessage(
            envelope.EventId,
            envelope.Type,
            envelope.PartitionKey,
            topic,
            EventSerializer.Serialize(envelope),
            TruncateToMicroseconds(createdAt.ToUniversalTime()));
    }

    /// <summary>Counts one more attempt to publish the event, made before each send (successful or not).</summary>
    public void RecordAttempt()
    {
        Attempts++;
    }

    /// <summary>
    /// Marks the event as published at <paramref name="publishedAt"/> (stored in UTC, whole microseconds). Called only
    /// after the broker acknowledged the event.
    /// </summary>
    public void MarkPublished(DateTimeOffset publishedAt)
    {
        PublishedAt = TruncateToMicroseconds(publishedAt.ToUniversalTime());
    }

    /// <summary>Reads <see cref="Payload"/> back as an envelope.</summary>
    public EventEnvelope ReadEnvelope()
    {
        return EventSerializer.Deserialize(Payload);
    }

    private static DateTimeOffset TruncateToMicroseconds(DateTimeOffset value)
    {
        return value.AddTicks(-(value.Ticks % TimeSpan.TicksPerMicrosecond));
    }
}
